<div id="sidebar">

	<ul id="sidebarwidgeted">

	<li id="execphp-26" class="widget widget_execphp">			<div class="execphpwidget"><a href="#" class="manual-optin-trigger" data-optin-slug="ykbpeqptg9fsx8ml"><img src="http://web.archive.org/web/20160916225634im_/http://www.strangenotions.com/wp-content/uploads/10BestPosts-SidebarGraphic.png" height="" width=""/></a>
