<div class="header-ad"><div class="advertisement" data-ismobile="false" data-name="header" data-sz="728x90" data-kw="top"><div id="header728x90_frame" class="displayAd displayAd728x90Js" data-cb-ad-id="header728x90_frame"></div></div><div class="advertisement" data-ismobile="true" data-name="header_mobile" data-sz="320x50" data-kw="top"><div id="header_mobile320x50_frame" class="displayAd displayAd320x50Js" data-cb-ad-id="header_mobile320x50_frame"></div></div></div>		<article itemscope itemtype="http://schema.org/Article" data-details="{&quot;title&quot;:&quot;Arguing Abortion&quot;,&quot;author&quot;:[28448,&quot;Adam Gopnik&quot;,&quot;http:\/\/www.newyorker.com\/contributors\/adam-gopnik&quot;],&quot;wordCount&quot;:1560,&quot;paragraphCount&quot;:8}">
			<meta itemprop="url" content="http://web.archive.org/web/20160423035951/http://www.newyorker.com/news/daily-comment/arguing-abortion"/>
