			<header id="page-header">
				<div class="section-info">
											<figure>
							<a href="http://web.archive.org/web/20160423035951/http://www.newyorker.com/news/daily-comment" title="Daily Comment" itemprop="articleSection">
								<img src="/web/20160423035951im_/http://www.newyorker.com/wp-content/assets/dist/img/header_graphics/blog/daily-comment.png?2015-05-13" alt="Daily Comment"/>
