										<h4><a href="http://web.archive.org/web/20160423035951/http://www.newyorker.com/news/daily-comment" title="Daily Comment" itemprop="articleSection">Daily Comment</a></h4>
				</div>

				<hgroup id="masthead">
					<span class="timestamp "> <time datetime="20141128" itemprop="datePublished" content="2014-11-28">November 28, 2014</time></span>

					<h1 itemprop="name">Arguing Abortion</h1>

					<h3>By <span itemscope itemprop="author" itemtype="http://schema.org/Person"><meta itemprop="url" content="http://web.archive.org/web/20160423035951/http://www.newyorker.com/contributors/adam-gopnik"><a href="http://web.archive.org/web/20160423035951/http://www.newyorker.com/contributors/adam-gopnik" title="Adam Gopnik" rel="author" itemprop="url"><span itemprop="name">Adam Gopnik</span></a></span></h3>					<div class="color-footer social-hover">

    <nav class="social-buttons-js social-buttons-circle"><ul class="share-tools-curated large-block-grid-5 medium-block-grid-5 small-block-grid-5"><li class="fb-share"><a class="facebook-share-btn" href="http://web.archive.org/web/20160423035951/https://www.facebook.com/sharer/sharer.php?u=http://www.newyorker.com/news/daily-comment/arguing-abortion&amp;display=popup&amp;ref=plugin" data-template="https://www.facebook.com/sharer/sharer.php?u={{{url}}}&amp;display=popup&amp;ref=plugin" target="_blank">Share<span></span></a></li>
<li class="twitter-share"><a class="twitter-share-btn" href="http://web.archive.org/web/20160423035951/https://twitter.com/intent/tweet?original_referer=http://www.newyorker.com/news/daily-comment/arguing-abortion&amp;text=Arguing Abortion&amp;tw_p=tweetbutton&amp;url=http://www.newyorker.com/news/daily-comment/arguing-abortion&amp;via=adamgopnik" data-template="https://twitter.com/intent/tweet?original_referer={{{url}}}&amp;text={{{text}}}&amp;tw_p=tweetbutton&amp;url={{{url}}}&amp;via=adamgopnik" target="_blank">Tweet<span></span></a></li>
