  <div class="dropdown"><span class="i-plus"></span>
    <div class="dd-content">
      <h4>Share</h4>
      <ul>
        <li><a class="email i-email addthis_button_email"><img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs%3D">Email</a></li>
